// Turns test-results/perf.json (written by tests/e2e/perf.spec.ts) and the build output in dist/
// into docs/PERF.md. Run after `pnpm build && pnpm test:e2e perf.spec.ts`.
import { readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { gzipSync } from 'node:zlib';

const BUDGET = { drawCalls: 150, triangles: 300_000 };
const rows = JSON.parse(readFileSync('test-results/perf.json', 'utf8'));
const kb = (n) => `${(n / 1024).toFixed(1)} kB`;

const lines = [
  '# Performance report (T38)',
  '',
  'Generated by `node scripts/perf-report.mjs` from `tests/e2e/perf.spec.ts`. Every 3D screen is opened on the **medium** preset by a player with everything unlocked, left to run, and typed at for ten seconds by a scripted typist. The worst frame of the run is listed. Budget (ARCHITECTURE section 7): at most 150 draw calls and 300,000 triangles on medium. Frame time is not judged here: the test machine draws in software.',
  '',
  '| Screen | Draw calls | Triangles | Geometries | Textures | Programs | JS heap change | Within budget |',
  '| --- | ---: | ---: | ---: | ---: | ---: | ---: | :---: |',
];
for (const r of rows) {
  const ok = r.drawCalls <= BUDGET.drawCalls && r.triangles <= BUDGET.triangles;
  const heap = r.heapGrowthKB === null ? 'n/a' : `${r.heapGrowthKB} kB`;
  lines.push(
    `| ${r.route} | ${r.drawCalls} | ${r.triangles.toLocaleString('en-US')} | ${r.geometries} | ${r.textures} | ${r.programs} | ${heap} | ${ok ? 'yes' : '**NO**'} |`,
  );
}
lines.push(
  '',
  'JS heap change is the growth of the page’s heap over the ten seconds of typing, a rough check that nothing allocates without end (the browser collects garbage on its own schedule, so small swings are normal). Every screen is also checked to free its engine on leaving.',
  '',
  '## Bundle size',
  '',
  'Screens load on demand (`src/ui/lazyScreen.ts`), so a first visit downloads only the shell and the screen being opened.',
  '',
  '| File | Raw | Gzip |',
  '| --- | ---: | ---: |',
);
const dir = 'dist/assets';
const files = readdirSync(dir)
  .filter((f) => f.endsWith('.js'))
  .map((f) => {
    const buf = readFileSync(`${dir}/${f}`);
    return { f: f.replace(/-[A-Za-z0-9_]{8}\.js$/, '.js'), raw: statSync(`${dir}/${f}`).size, gz: gzipSync(buf).length };
  })
  .sort((a, b) => b.raw - a.raw);
for (const x of files) lines.push(`| ${x.f} | ${kb(x.raw)} | ${kb(x.gz)} |`);
const total = files.reduce((a, x) => ({ raw: a.raw + x.raw, gz: a.gz + x.gz }), { raw: 0, gz: 0 });
lines.push(`| **All scripts** | ${kb(total.raw)} | ${kb(total.gz)} |`, '');
writeFileSync('docs/PERF.md', lines.join('\n'));
console.log('wrote docs/PERF.md');
